def get_total_number_of_sequences(m, n, memo=None):
    if memo is None:
        memo = {}

    def dp(pos, prev):
        if pos == n:
            return 1
        if (pos, prev) in memo:
            return memo[(pos, prev)]

        count = 0
        for curr in range(max(prev * 2, 1), m + 1):
            count += dp(pos + 1, curr)

        memo[(pos, prev)] = count
        return count

    return dp(0, 0)
```

