    if last_occurrence == -1:
        return False  # x not found

    # Check if count of x exceeds n/2
    count = last_occurrence - first_occurrence + 1
    return count > n / 2


def binary_search_first(arr, low, high, x):
    if high >= low:
        mid = (low + high) // 2
        if (mid == 0 or arr[mid - 1] < x) and arr[mid] == x:
            return mid
        elif x < arr[mid]:
            return binary_search_first(arr, low, mid - 1, x)
        else:
            return binary_search_first(arr, mid + 1, high, x)
    return -1


def binary_search_last(arr, low, high, x):
